CREATE VIEW [dbo].[View_FieldForceMarket]ASSELECT        MKT.MarketId, MKT.MarketName, MKT.SubTerritoryId, NSM.EmpMasterCode AS NSMCode, RSM.EmpMasterCode AS RSMCode, ASM.EmpMasterCode AS ASMCode, MIO.EmpMasterCode AS MIOCodeFROM            dbo.tbl_Group AS GP  with (nolock)  LEFT OUTER JOIN                         dbo.tblRegion AS RGN  with (nolock)   ON GP.GroupId = RGN.GroupId LEFT OUTER JOIN                         dbo.tblArea AS ARA  with (nolock)  ON RGN.RegionId = ARA.RegionId LEFT OUTER JOIN                         dbo.tblTerritory AS TTR  with (nolock)  ON ARA.AreaId = TTR.AreaId LEFT OUTER JOIN                         dbo.tblSubTerritory AS STTR  with (nolock)  ON TTR.TerritoryId = STTR.TerritoryId LEFT OUTER JOIN                         dbo.tblMarket AS MKT  with (nolock)  ON STTR.SubTerritoryId = MKT.SubTerritoryId LEFT OUTER JOIN                             (SELECT        N.GroupId, EGI.EmpMasterCode, EGI.EmpName                               FROM            dbo.tblNSMInfo AS N  with (nolock)  LEFT OUTER JOIN                                                         dbo.tblEmpGeneralInfo AS EGI  with (nolock)  ON N.EmployeeId = EGI.EmpInfoId                               WHERE        (N.IsActive = 1)) AS NSM ON NSM.GroupId = GP.GroupId LEFT OUTER JOIN                             (SELECT        RM.RegionId, EGI.EmpMasterCode, EGI.EmpName, urR.RoleName EmpRole                               FROM            dbo.tblRSMInfo AS RM  with (nolock) 							   LEFT JOIN   dbo.tblEmpGeneralInfo AS EGI  with (nolock)  ON RM.EmployeeId = EGI.EmpInfoId							    LEFT   JOIN  dbo.tblUser AS ur  with (nolock)  ON ur.EmpInfoId = EGI.EmpInfoId							    LEFT   JOIN dbo.tbl_UserRoleInfo AS urR  with (nolock)  ON urR.UserRoleID = ur.UserRoleID                                WHERE        (RM.IsActive = 1)) AS RSM ON RGN.RegionId = RSM.RegionId LEFT OUTER JOIN                             (   SELECT        AM.AreaId, EGI.EmpMasterCode, EGI.EmpName,  urR.RoleName  EmpRole                               FROM            dbo.tblASMInfo AS AM   with (nolock) 							   LEFT   JOIN  dbo.tblEmpGeneralInfo AS EGI  with (nolock)  ON AM.EmployeeId = EGI.EmpInfoId							     LEFT   JOIN  dbo.tblUser AS ur  with (nolock)  ON ur.EmpInfoId = EGI.EmpInfoId							    LEFT   JOIN dbo.tbl_UserRoleInfo AS urR  with (nolock)  ON urR.UserRoleID = ur.UserRoleID                                WHERE        (AM.IsActive = 1)) AS ASM ON ARA.AreaId = ASM.AreaId LEFT OUTER JOIN                             (   SELECT        M.TerritoryId, EGI.EmpMasterCode, EGI.EmpName, urR.RoleName  EmpRole                               FROM            dbo.tblMIOInfo AS M  with (nolock) 							    LEFT   JOIN dbo.tblEmpGeneralInfo AS EGI  with (nolock)  ON M.EmployeeId = EGI.EmpInfoId								 LEFT   JOIN  dbo.tblUser AS ur  with (nolock)  ON ur.EmpInfoId = EGI.EmpInfoId							    LEFT   JOIN dbo.tbl_UserRoleInfo AS urR  with (nolock)  ON urR.UserRoleID = ur.UserRoleID                                WHERE        (M.IsActive = 1)) AS MIO ON TTR.TerritoryId = MIO.TerritoryIdWHERE        (GP.IsActive = 1) AND (RGN.IsActive = 1) AND (ARA.IsActive = 1) AND (TTR.IsActive = 1) AND (STTR.IsActive = 1) AND (MKT.IsActive = 1)